function _stripComment(s){ var out='',inS=false,inD=false;
  for(var i=0;i<s.length;i++){ var c=s[i];
    if(c==="'"&&!inD){ inS=!inS; } else if(c==='"'&&!inS){ inD=!inD; }
    else if(c==='#'&&!inS&&!inD){ break; }
    out+=c; }
  return out.replace(/\s+$/,'');
}
function _unq(s){ s=(s||'').trim(); if((s[0]==='"'&&s[s.length-1]==='"')||(s[0]==="'"&&s[s.length-1]==="'")) return s.slice(1,-1); return s; }
function _scalar(s){ s=(s||'').trim();
  if(s===''||s==='~'||/^null$/i.test(s)) return null;
  if(/^true$/i.test(s)) return true; if(/^false$/i.test(s)) return false;
  if((s[0]==='"'&&s[s.length-1]==='"')||(s[0]==="'"&&s[s.length-1]==="'")) return _unq(s);
  if(/^-?\d+$/.test(s)) return parseInt(s,10);
  if(/^-?\d+\.\d+$/.test(s)) return parseFloat(s);
  return _unq(s);
}
function _tokenize(text){ var lines=String(text).replace(/\r\n/g,'\n').split('\n'); var toks=[];
  for(var i=0;i<lines.length;i++){ var raw=lines[i]; if(/^\s*$/.test(raw)) continue;
    var content=_stripComment(raw).replace(/^\s+/,''); if(content==='') continue;
    var indent=raw.length-raw.replace(/^\s*/,'').length;
    toks.push({indent:indent,content:content}); }
  return toks;
}
function parseYaml(text){
  var toks=_tokenize(text); var errors=[];
  function block(toks,start,indent){
    var first=toks[start];
    if(first.content==='-'||first.content.indexOf('- ')===0){
      var arr=[],i=start;
      while(i<toks.length && toks[i].indent===indent && (toks[i].content==='-'||toks[i].content.indexOf('- ')===0)){
        var item=toks[i].content.slice(1).replace(/^\s+/,'');
        if(item.indexOf(':')>0 && !/^["'].*:["']?$/.test(item)){
          var sub=toks.slice(0,i).concat([{indent:indent+2,content:item}]);
          var deeper=i+1;
          while(deeper<toks.length && toks[deeper].indent>indent){ sub.push(toks[deeper]); deeper++; }
          var parsed=block(sub,sub.length-(deeper-i),indent+2);
          arr.push(parsed.value); i=deeper;
        } else { arr.push(_scalar(item)); i++; }
      }
      return {value:arr,next:i};
    }
    var obj={},i=start;
    while(i<toks.length && toks[i].indent===indent && toks[i].content.indexOf('- ')!==0 && toks[i].content!=='-'){
      var c=toks[i].content, ci=c.indexOf(':');
      if(ci<0){ errors.push('行格式错误: '+c); i++; continue; }
      var key=_unq(c.slice(0,ci)), val=c.slice(ci+1).trim();
      if(val===''){
        if(i+1<toks.length && toks[i+1].indent>indent){ var sub2=block(toks,i+1,toks[i+1].indent); obj[key]=sub2.value; i=sub2.next; }
        else { obj[key]=null; i++; }
